import{_ as t,a,c as n,ac as i}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse(`{"title":"第四册：流利英语 · Lesson 27 The 'Vasa'","description":"学习 第三条件句与过去反事实，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第四册：流利英语 · Lesson 27 The 'Vasa'","description":"学习 第三条件句与过去反事实，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第4册课时","summary":"学习 第三条件句与过去反事实，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第四册：流利英语 · Lesson 26 The past life of the earth","link":"/life/english/new-concept/book-4/unit-04/lesson-026"},"next":{"text":"第四册：流利英语 · Lesson 28 Patients and doctors","link":"/life/english/new-concept/book-4/unit-04/lesson-028"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第四册：流利英语 · Lesson 26 The past life of the earth","link":"/life/english/new-concept/book-4/unit-04/lesson-026"},"next":{"text":"第四册：流利英语 · Lesson 28 Patients and doctors","link":"/life/english/new-concept/book-4/unit-04/lesson-028"}},"headers":[],"relativePath":"life/english/new-concept/book-4/unit-04/lesson-027.md","filePath":"life/english/new-concept/book-4/unit-04/lesson-027.md"}`),o={name:"life/english/new-concept/book-4/unit-04/lesson-027.md"};function l(s,e,h,d,r,c){return a(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="第四册-流利英语-·-lesson-27-the-vasa" tabindex="-1">第四册：流利英语 · Lesson 27 The &#39;Vasa&#39; <a class="header-anchor" href="#第四册-流利英语-·-lesson-27-the-vasa" aria-label="Permalink to &quot;第四册：流利英语 · Lesson 27 The &#39;Vasa&#39;&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-4/contents">本册目录</a> · <a href="/life/english/new-concept/book-4/unit-04/overview">单元 4</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>以沉船历史和工程解释为阅读场景，学习把事件叙述、原因分析与事后假设分开。不要因为知道事故结局，就把当时所有决策描写成显然错误。重点练习过去反事实条件句，说明如果某项条件不同，结果可能如何变化，同时承认无法直接观察替代历史。</p><p>本课以主题阅读带动语言分析，学习重点如下。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>vessel</td><td>/ˈvesəl/</td><td>n.</td><td>船舶</td><td>a wooden vessel</td></tr><tr><td>stability</td><td>/stəˈbɪləti/</td><td>n.</td><td>稳定性</td><td>improve stability</td></tr><tr><td>salvage</td><td>/ˈsælvɪdʒ/</td><td>v.</td><td>打捞</td><td>salvage a wreck</td></tr><tr><td>balance</td><td>/ˈbæləns/</td><td>n.</td><td>平衡</td><td>check the balance</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>set sail — 起航</li><li>in hindsight — 事后回看</li></ul><h2 id="语法讲解-第三条件句与过去反事实" tabindex="-1">语法讲解：第三条件句与过去反事实 <a class="header-anchor" href="#语法讲解-第三条件句与过去反事实" aria-label="Permalink to &quot;语法讲解：第三条件句与过去反事实&quot;">​</a></h2><p>If + had done，主句 would/could/might have done 用来设想已经过去的情形。If the team had checked the balance, they might have noticed the problem. 并不表示检查实际发生了。would have 通常把结果说得较确定，might have 更适合不确定的历史推测。不能把 if 从句写成 if would have checked。除非有明确时间转换，不要把过去条件与现在结果形式随意混用。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>If the model had been tested earlier, the designers might have noticed the imbalance.</p></blockquote><p>如果模型更早接受了测试，设计者可能会注意到不平衡。</p><p>had been tested 是过去完成时被动条件；might have noticed 表对过去替代结果的谨慎推测。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>If the model would have been tested 错把结果形式放入条件；应写 had been tested。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>朗读 had been tested 和 might have noticed，注意两组弱读；录音后听辨条件与结果是否被换位。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>The model tilted during its first public demonstration. If we had tested it with a full load, we might have detected the imbalance. Future checks should include several loading conditions.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>写三句虚构船模事故复盘：事实、反事实假设、今天的改进。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>事实与假设不混写，末句将反思转成明确可测试的改进。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>示例是否声称模型确实更早接受测试？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 没有。</p><p><strong>解析：</strong> 它构造过去反事实条件。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>填空：If they had delayed departure, they might ___ avoided the storm.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> have</p><p><strong>解析：</strong> 结果分句用 might have + 过去分词。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>将主动条件 if they had tested the model 改为被动。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> if the model had been tested</p><p><strong>解析：</strong> 过去完成时被动使用 had been tested。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：第三条件句与过去反事实。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-4/unit-04/grammar">单元语法</a> · <a href="/life/english/new-concept/book-4/unit-04/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-4/unit-04/review">单元自测</a></p><p><a href="/life/english/new-concept/book-4/unit-04/lesson-026">上一课</a> · <a href="/life/english/new-concept/book-4/unit-04/overview">单元目录</a> · <a href="/life/english/new-concept/book-4/unit-04/lesson-028">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const b=t(o,[["render",l]]);export{u as __pageData,b as default};
